package com.shopsphere.dao;
import com.shopsphere.model.Address;
import com.shopsphere.util.DBConnection;
import java.sql.*;
import java.util.*;
public class AddressDAO {
    public Address findById(Long id) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT * FROM addresses WHERE id=?")) { p.setLong(1, id); try (ResultSet r = p.executeQuery()) { return r.next() ? map(r) : null; } } catch (SQLException e) { return null; } }
    public List<Address> findByUserId(Long userId) { List<Address> l = new ArrayList<>(); try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT * FROM addresses WHERE user_id=? ORDER BY is_default DESC, id DESC")) { p.setLong(1, userId); try (ResultSet r = p.executeQuery()) { while (r.next()) l.add(map(r)); } } catch (SQLException e) {} return l; }
    public boolean create(Address a) { try (Connection c = DBConnection.getConnection()) { if (a.isDefault()) { try (PreparedStatement p = c.prepareStatement("UPDATE addresses SET is_default=FALSE WHERE user_id=?")) { p.setLong(1, a.getUserId()); p.executeUpdate(); } } try (PreparedStatement p = c.prepareStatement("INSERT INTO addresses (user_id,recipient_name,phone,address_line1,address_line2,city,state,postal_code,country,is_default) VALUES (?,?,?,?,?,?,?,?,?,?)", Statement.RETURN_GENERATED_KEYS)) { p.setLong(1, a.getUserId()); p.setString(2, a.getRecipientName()); p.setString(3, a.getPhone()); p.setString(4, a.getAddressLine1()); p.setString(5, a.getAddressLine2()); p.setString(6, a.getCity()); p.setString(7, a.getState()); p.setString(8, a.getPostalCode()); p.setString(9, a.getCountry()); p.setBoolean(10, a.isDefault()); if (p.executeUpdate() > 0) { try (ResultSet k = p.getGeneratedKeys()) { if (k.next()) a.setId(k.getLong(1)); } return true; } } } catch (SQLException e) {} return false; }
    public boolean setDefault(Long userId, Long id) { try (Connection c = DBConnection.getConnection()) { try (PreparedStatement p = c.prepareStatement("UPDATE addresses SET is_default=FALSE WHERE user_id=?")) { p.setLong(1, userId); p.executeUpdate(); } try (PreparedStatement p = c.prepareStatement("UPDATE addresses SET is_default=TRUE WHERE id=? AND user_id=?")) { p.setLong(1, id); p.setLong(2, userId); return p.executeUpdate() > 0; } } catch (SQLException e) { return false; } }
    public boolean delete(Long id, Long userId) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("DELETE FROM addresses WHERE id=? AND user_id=?")) { p.setLong(1, id); p.setLong(2, userId); return p.executeUpdate() > 0; } catch (SQLException e) { return false; } }
    private Address map(ResultSet r) throws SQLException { Address a = new Address(); a.setId(r.getLong("id")); a.setUserId(r.getLong("user_id")); a.setRecipientName(r.getString("recipient_name")); a.setPhone(r.getString("phone")); a.setAddressLine1(r.getString("address_line1")); a.setAddressLine2(r.getString("address_line2")); a.setCity(r.getString("city")); a.setState(r.getString("state")); a.setPostalCode(r.getString("postal_code")); a.setCountry(r.getString("country")); a.setDefault(r.getBoolean("is_default")); return a; }
}
